//! EN-US: A fresh API/client tree reuses private on-disk previews, not retained GTK objects.
//! PT-BR: Um cliente/API novo reutiliza prévias privadas em disco, sem reter objetos GTK antigos.
use super::*;
use actions::tests::{mock,pump,until};
#[cfg(test)]pub(crate) fn exercise(context:&gtk::glib::MainContext){
    let(api,backend,server)=tokio::runtime::Handle::current().block_on(mock());let channel=Uuid::new_v4();let user=Uuid::new_v4();let now=chrono::Utc::now();let keys:Vec<_>=(0..8).map(|_|Uuid::new_v4()).collect();
    let mut png=std::io::Cursor::new(Vec::new());let pixels=image::RgbaImage::from_fn(640,320,|x,y|{let n=x.wrapping_mul(1234567)^y.wrapping_mul(7654321);image::Rgba([n as u8,(n>>8)as u8,(n>>16)as u8,255])});image::DynamicImage::ImageRgba8(pixels).write_to(&mut png,image::ImageFormat::Png).unwrap();let png=png.into_inner();
    {let mut state=backend.lock().unwrap();for key in &keys{state.attachment_thumbnails.insert(format!("/attachments/{key}/thumbnail"),png.clone());}}
    let messages:Vec<Message>=keys.iter().enumerate().map(|(i,key)|serde_json::from_value(serde_json::json!({"id":Uuid::new_v4(),"channel_id":channel,"created_at":now+chrono::Duration::seconds(i as i64),"attachments":[{"id":key,"mime_type":"image/png","original_file_name":"photo.png","size_bytes":png.len(),"thumbnail_width":640,"thumbnail_height":320,"moderation_status":"clean","created_at":now}]})).unwrap()).collect();
    let target:Channel=serde_json::from_value(serde_json::json!({"id":channel,"name":"Disk cache","created_at":now})).unwrap();
    let open=|api:crate::api::ApiClient|{let chat=ChatModel::builder().launch(ChatInit{api:Some(api),active_channel:Some(target.clone()),messages:messages.clone(),user_id:Some(user),..Default::default()}).detach();chat.emit(ChatMsg::MediaPreferences(Default::default()));chat.emit(ChatMsg::SetAccess{user_id:user,access:crate::models::Access::direct()});let window=adw::Window::builder().default_width(900).default_height(750).content(chat.widget()).build();window.present();(chat,window)};
    let begin=std::time::Instant::now();let(chat,window)=open(api.clone());until(context,||keys.iter().all(|id|chat.model().transfers.textures.contains_key(id)));let cold=begin.elapsed().as_millis();let cache=api.thumbnail_cache(user).unwrap();
    until(context,||tokio::runtime::Handle::current().block_on(cache.usage())>=png.len() as u64*8);performance::settle(context);
    let count=||backend.lock().unwrap().requests.iter().filter(|(_,p,_)|p.ends_with("/thumbnail")).count();assert_eq!(count(),8);window.set_content(None::<&gtk::Widget>);window.close();drop(chat);drop(window);pump(context);
    let fresh=crate::api::ApiClient::new(api.base_url()).unwrap();let begin=std::time::Instant::now();let(chat,window)=open(fresh);until(context,||keys.iter().all(|id|chat.model().transfers.textures.contains_key(id)));let warm=begin.elapsed().as_millis();assert_eq!(count(),8,"a fresh client must use disk thumbnails without more thumbnail HTTP requests");
    println!("Papo disk thumbnail comparison: {}",serde_json::json!({"cold_preview_ms":cold,"fresh_client_preview_ms":warm,"cold_thumbnail_requests":8,"fresh_client_thumbnail_requests":0,"images":8,"source_png_bytes":png.len(),"note":"synthetic local backend; fresh client tree, same authorized account; timings are observations, not a network benchmark"}));
    chat.emit(ChatMsg::ApplyChange(Change::Moderation(messages[0].id,keys[0],"blocked".into())));pump(context);let key=crate::media::disk::Key{channel,message:messages[0].id,resource:keys[0],revision:String::new()};assert!(chat.model().transfers.disk.as_ref().unwrap().ticket(key).is_none());chat.emit(ChatMsg::ClearMediaCache(Uuid::new_v4()));until(context,||tokio::runtime::Handle::current().block_on(cache.usage())==0);window.set_content(None::<&gtk::Widget>);window.close();drop(chat);server.abort();pump(context);
}
